// Konfigurasi milik operator, TIDAK dibaca dari pesan WhatsApp.
// Isi nanti setelah nomor owner, outlet, dan device diverifikasi.
// Contoh struktur owner: { phone: "62...", deviceId: "...@s.whatsapp.net",
//   gowaDeviceId: "session-id-dari-GoWA", ownerId: "...", outletIds: ["..."], active: true }
// Jangan menaruh password, API key, atau webhook secret di node ini.
const config = {
  liveEnabled: false,
  databaseReady: false,
  aiReady: false,
  sendReplies: false,
  ingressControlsReady: false,
  timezone: "Asia/Jakarta",
  maxMessageAgeSeconds: 300,
  maxQuestionLength: 1500,
  owners: []
};
return [{ json: { config }, binary: $input.first().binary }];

const config = $json.config;
const reject = (status, reason) => [{ json: { accepted: false, httpStatus: status, reason } }];
if (!config.liveEnabled || !config.ingressControlsReady) return reject(503, "WORKFLOW_NOT_READY");
try {
  const secret = $env.CASIR_GOWA_WEBHOOK_SECRET;
  if (typeof secret !== "string" || secret.length < 32) return reject(503, "WEBHOOK_SECRET_NOT_READY");
  const source = $("Pesan WhatsApp Masuk").first();
  const signature = source.json.headers?.["x-hub-signature-256"];
  if (typeof signature !== "string" || !/^sha256=[a-f0-9]{64}$/i.test(signature))
    return reject(401, "INVALID_SIGNATURE");
  const raw = await this.helpers.getBinaryDataBuffer(0, "data");
  if (!raw.length || raw.length > 65536) return reject(413, "BODY_SIZE");
  const crypto = require("crypto");
  const digest = crypto.createHmac("sha256", secret).update(raw).digest();
  const supplied = Buffer.from(signature.slice(7), "hex");
  if (!crypto.timingSafeEqual(digest, supplied)) return reject(401, "INVALID_SIGNATURE");
  let event;
  try { event = JSON.parse(raw.toString("utf8")); }
  catch { return reject(400, "INVALID_JSON"); }
  return [{ json: { accepted: true, httpStatus: 200, event } }];
} catch {
  // Missing raw body, blocked env access, or unavailable crypto: fail closed.
  return reject(503, "VERIFICATION_UNAVAILABLE");
}

const event = $("Verifikasi Webhook GoWA").first().json.event;
const config = $("Konfigurasi Casir").first().json.config;
const ignore = reason => [{ json: { valid: false, reason } }];
if (!event || event.event !== "message") return ignore("NOT_MESSAGE");
const p = event.payload;
if (!p || p.is_from_me !== false || p.is_group === true) return ignore("SELF_OR_GROUP");
if (typeof p.from !== "string" || !/^[1-9][0-9]{7,14}@s\.whatsapp\.net$/.test(p.from))
  return ignore("UNSUPPORTED_SENDER");
if (typeof p.chat_id !== "string" || !/^[1-9][0-9]{7,14}@s\.whatsapp\.net$/.test(p.chat_id))
  return ignore("GROUP_OR_UNSUPPORTED_CHAT");
if (typeof event.device_id !== "string" || !event.device_id) return ignore("MISSING_DEVICE");
if (typeof p.id !== "string" || !/^[A-Za-z0-9_-]{1,128}$/.test(p.id)) return ignore("MISSING_MESSAGE_ID");
if (typeof p.body !== "string" || !p.body.trim() || p.body.length > config.maxQuestionLength)
  return ignore("INVALID_TEXT");
const timestamp = typeof p.timestamp === "string" ? Date.parse(p.timestamp) : NaN;
const age = Date.now() - timestamp;
if (!Number.isFinite(timestamp) || age > config.maxMessageAgeSeconds * 1000 || age < -60000)
  return ignore("STALE_MESSAGE");
return [{ json: { valid: true, question: p.body.trim(), sender: p.from.split("@")[0],
  deviceId: event.device_id, messageId: p.id, receivedAt: new Date().toISOString() } }];

const message = $json;
const config = $("Konfigurasi Casir").first().json.config;
const matches = config.owners.filter(owner => owner.active === true &&
  owner.phone === message.sender && owner.deviceId === message.deviceId);
const deny = () => [{ json: { authorized: false, reason: "OWNER_NOT_AUTHORIZED" } }];
if (matches.length !== 1) return deny();
const owner = matches[0];
if (typeof owner.ownerId !== "string" || !owner.ownerId ||
    typeof owner.gowaDeviceId !== "string" || !owner.gowaDeviceId ||
    !Array.isArray(owner.outletIds) || !owner.outletIds.length || owner.outletIds.length > 20 ||
    owner.outletIds.some(v => typeof v !== "string" || !/^[A-Za-z0-9_-]{1,100}$/.test(v)))
  return deny();
// Payload outletId/role, nama pengirim, dan instruksi AI tidak memberi hak akses.
return [{ json: { authorized: true, question: message.question, sender: message.sender,
  deviceId: owner.deviceId, gowaDeviceId: owner.gowaDeviceId, ownerId: owner.ownerId,
  allowedOutletIds: [...new Set(owner.outletIds)], messageId: message.messageId,
  receivedAt: message.receivedAt } }];

const value = $json;
const fallback = "Laporan belum dapat diambil. Silakan coba lagi atau hubungi Admin. Tidak ada data penjualan atau stok yang diubah.";
let message = typeof value.output === "string" ? value.output.trim() : fallback;
if (value.source !== "system" && (!Array.isArray(value.intermediateSteps) || value.intermediateSteps.length === 0)) {
  message = "Sebutkan jenis laporan, outlet, dan tanggal yang ingin diperiksa. Saya belum mengambil data untuk pertanyaan ini.";
}
if (!message || /postgres(?:ql)?:\/\/|api[_ -]?key\s*[:=]|Bearer\s+[A-Za-z0-9]|eyJ[A-Za-z0-9_-]{10,}\.|ECONNREFUSED|SELECT\s+.+\s+FROM/i.test(message)) message = fallback;
if (message.length > 3500) message = message.slice(0, 3350) + "\n\n[Jawaban dipotong. Persempit periode atau jenis laporan.]";
const owner = $("Otorisasi Owner").first().json;
if (owner.authorized !== true) throw new Error("UNAUTHORIZED_REPLY");
return [{ json: { message, phone: owner.sender, messageId: owner.messageId, deviceId: owner.gowaDeviceId } }];

return [{ json: {
  status: "DRAFT - BELUM LIVE",
  databaseConnected: false, whatsappSent: false, aiCalled: false,
  reports: ["penjualan", "metode pembayaran", "harian", "sesi kasir", "produk terlaris",
    "stok produk", "bahan baku", "stock opname", "permintaan bahan", "mutasi stok", "transaksi", "katalog"],
  next: "Lengkapi owner-outlet, webhook secret dan kontrol ingress, credential database read-only; uji integrasi sebelum mengaktifkan."
} }];

