={{ (() => {
const owner = $('Otorisasi Owner').first().json;
const config = $('Konfigurasi Casir').first().json.config;
if (owner.authorized !== true || config.databaseReady !== true || !Array.isArray(owner.allowedOutletIds) || !owner.allowedOutletIds.length) throw new Error('REPORT_ACCESS_DENIED');
const start = $fromAI('start_date', 'Tanggal mulai YYYY-MM-DD WIB, inklusif. Untuk stok terkini tetap isi tanggal hari ini.', 'string');
const end = $fromAI('end_date', 'Tanggal akhir YYYY-MM-DD WIB, inklusif; maksimum 366 hari.', 'string');
const outlet = $fromAI('outlet_id', 'ID outlet dari daftar yang diizinkan; kosong berarti semua outlet milik owner.', 'string', '');
const validDate = value => typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(value + 'T00:00:00Z')) && new Date(value + 'T00:00:00Z').toISOString().slice(0,10) === value && value >= '2000-01-01' && value <= '2100-12-31';
if (!validDate(start) || !validDate(end) || end < start || (Date.parse(end)-Date.parse(start))/86400000 > 365) throw new Error('INVALID_REPORT_PERIOD');
if (outlet !== '' && !owner.allowedOutletIds.includes(outlet)) throw new Error('OUTLET_NOT_AUTHORIZED');
return [JSON.stringify(owner.allowedOutletIds), start, end, outlet];
})() }}

